---

### 🎨 一、核心原型设计：React 19 UI Slots 纯净挂载与生命周期守卫

为保证在注入器热重载与 `dev_uninject_plugin` 卸载时达到 **DOM 零残留、无游离事件监听、无样式污染**，UI 插槽容器设计采用严格的 `AbortController` 绑定生命周期：

```tsx
// client/components/GroupChatSlotHost.tsx
import React, { useEffect, useRef, useSyncExternalStore } from 'react';

export interface GroupChatSlotProps {
  slotId: string;
  onAction?: (action: string, payload: unknown) => void;
}

export const GroupChatSlotHost: React.FC<GroupChatSlotProps> = ({ slotId, onAction }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const ac = new AbortController();
    const { signal } = ac;

    // 绑定宿主通信事件与窗口尺寸自适应监听
    window.addEventListener(
      'dsh:group_chat:event',
      (e: CustomEvent) => {
        if (!signal.aborted) {
          onAction?.(e.detail.type, e.detail.data);
        }
      },
      { signal }
    );

    return () => {
      // 卸载守卫：强制中断信号、清除 DOM 内部附加节点，杜绝热重载“鬼影残留”
      ac.abort();
      if (containerRef.current) {
        containerRef.current.replaceChildren();
      }
    };
  }, [slotId, onAction]);

  return (
    <div 
      ref={containerRef} 
      data-dsh-slot={slotId}
      className="dsh-group-chat-root flex flex-col h-full w-full bg-background text-foreground select-none"
    >
      <div className="slot-content-wrapper flex-1 overflow-y-auto px-4 py-3">
        {/* 动态渲染：决策卡片 / 流式会话气泡 / 成员状态微徽标 */}
      </div>
    </div>
  );
};

