---

### 📦 前端原型核心实现与关键代码骨架

#### 1. React 19 UI Slots 沙箱与零残留守卫 (`GroupChatSlotHost.tsx`)
针对热重载拔插与动态注入场景，利用 `AbortController` 绑定生命周期，确保卸载时同步阻断未决微任务，根绝 DOM 悬挂与鬼影：

```tsx
import React, { useEffect, useRef, useState, useTransition } from 'react';

export interface SlotHostProps {
  roomId: string;
  traceId: string;
  renderSlot: (signal: AbortSignal) => React.ReactNode;
  onUnmountCleanup?: () => void;
}

export const GroupChatSlotHost: React.FC<SlotHostProps> = ({
  roomId,
  traceId,
  renderSlot,
  onUnmountCleanup,
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [isPending, startTransition] = useTransition();
  const [slotContent, setSlotContent] = useState<React.ReactNode>(null);

  useEffect(() => {
    const controller = new AbortController();
    const { signal } = controller;

    startTransition(() => {
      if (!signal.aborted) {
        setSlotContent(renderSlot(signal));
      }
    });

    return () => {
      // 1. 信号熔断：立即废弃所有在途的异步渲染与回调
      controller.abort();
      // 2. 状态清空与作用域卸载
      setSlotContent(null);
      if (onUnmountCleanup) {
        onUnmountCleanup();
      }
      // 3. DOM 垃圾回收兜底：清理一切未决挂载节点
      if (containerRef.current) {
        containerRef.current.replaceChildren();
      }
    };
  }, [roomId, traceId, renderSlot, onUnmountCleanup]);

  return (
    <div
      ref={containerRef}
      className="dsh-slot-host-wrapper"
      data-room-id={roomId}
      data-trace-id={traceId}
      style={{ opacity: isPending ? 0.7 : 1, transition: 'opacity 150ms ease-out' }}
    >
      {slotContent}
    </div>
  );
};

