### 🧹 3. 严格契约：UI Slot 挂载守卫与热重载零鬼影清理
*对齐 `dsh-super-injector` 的“卸载即净、热重载即刷”宿主契约。*

```typescript
// React 19 Slot Host 挂载守卫与清理规范原型
export function useGroupChatSlotHost(slotId: string, injectorHook: InjectorLifecycle) {
  useEffect(() => {
    const abortController = new AbortController();
    const domAnchor = document.getElementById(`dsh-slot-${slotId}`);

    // 1. 挂载时接入通信网桥，注入独立 traceId 隔离并发
    injectorHook.bindSlotBridge(slotId, { signal: abortController.signal });

    return () => {
      // 2. 卸载/热重载触发：级联中断网络流，解除所有 EventListener
      abortController.abort();
      injectorHook.unbindSlotBridge(slotId);

      // 3. 强制清理微任务与残留 Portal DOM，确保卸载后 DOM 树与内存净残留
      if (domAnchor) domAnchor.replaceChildren();
    };
  }, [slotId, injectorHook]);
}

